package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"    // PIC X len=1 = "N"
var WsFirstFlag string = "Y" // PIC X len=1 = "Y"
var WsPrevBranch string = "  "   // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "  // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                 // PIC 99 len=2 = 0
var WsAmtEd string                      // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                      // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                      // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var inputLines []string
var inputIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func parseAmt(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(t)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-2)
}

func storeWithDigits(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	tv := v.Truncate(scale)
	if tv.IsZero() {
		return tv
	}
	sign := tv.Sign()
	av := tv.Abs()
	intPart := av.Truncate(0)
	fracPart := av.Sub(intPart)
	intStr := intPart.String()
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
		intPart, _ = decimal.NewFromString(intStr)
	}
	newAv := intPart.Add(fracPart)
	if sign < 0 {
		newAv = newAv.Neg()
	}
	return newAv
}

func storeSkipped(v int64) int64 {
	if v >= 0 {
		if v >= 100 {
			v = v % 100
		}
		return v
	}
	abs := -v
	if abs >= 100 {
		abs = abs % 100
	}
	return -abs
}

func formatEdited(v decimal.Decimal, pic string) string {
	signWanted := false
	signChar := ' '
	basePic := pic
	if len(pic) > 0 && pic[0] == '-' {
		signWanted = true
		if v.Sign() < 0 {
			signChar = '-'
		} else {
			signChar = ' '
		}
		basePic = pic[1:]
	}
	dotIdx := strings.Index(basePic, ".")
	var intPic, fracPic string
	var scale int
	if dotIdx != -1 {
		intPic = basePic[:dotIdx]
		fracPic = basePic[dotIdx+1:]
		scale = len(fracPic)
	} else {
		intPic = basePic
		fracPic = ""
		scale = 0
	}
	_ = fracPic
	capInt := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			capInt++
		}
	}
	av := v.Abs()
	scaled := av.Shift(int32(scale))
	scaledInt := scaled.Truncate(0)
	s := scaledInt.String()
	var integerRaw, fractionalRaw string
	if scale == 0 {
		integerRaw = s
		fractionalRaw = ""
	} else {
		if len(s) <= scale {
			integerRaw = "0"
			fractionalRaw = strings.Repeat("0", scale-len(s)) + s
		} else {
			integerRaw = s[:len(s)-scale]
			fractionalRaw = s[len(s)-scale:]
		}
	}
	if len(integerRaw) > capInt {
		integerRaw = integerRaw[len(integerRaw)-capInt:]
	}
	if len(integerRaw) < capInt {
		integerRaw = strings.Repeat("0", capInt-len(integerRaw)) + integerRaw
	}
	intOut := make([]rune, len(intPic))
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intOut[i] = rune(integerRaw[digitIdx])
			digitIdx++
		} else if ch == ',' {
			intOut[i] = ','
		} else {
			intOut[i] = ch
		}
	}
	suppressionStill := true
	for i, ch := range intPic {
		if ch == 'Z' {
			if suppressionStill && intOut[i] == '0' {
				intOut[i] = ' '
			} else if suppressionStill && intOut[i] != '0' {
				suppressionStill = false
			} else {
				suppressionStill = false
			}
		} else if ch == '9' {
			suppressionStill = false
		}
		_ = i
	}
	for i, ch := range intPic {
		if ch == ',' {
			allSuppressed := true
			for j := 0; j < i; j++ {
				pj := intPic[j]
				if pj == 'Z' || pj == '9' {
					if intOut[j] != ' ' {
						allSuppressed = false
						break
					}
				}
			}
			if allSuppressed {
				intOut[i] = ' '
			} else {
				intOut[i] = ','
			}
		}
	}
	var sb strings.Builder
	if signWanted {
		sb.WriteRune(signChar)
	}
	sb.WriteString(string(intOut))
	if dotIdx != -1 {
		sb.WriteRune('.')
		sb.WriteString(fractionalRaw)
	}
	return sb.String()
}

func formatAmtEd(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatBalEd(v decimal.Decimal) string {
	return formatEdited(v, "-Z,ZZZ,ZZ9.99")
}
func formatTotEd(v decimal.Decimal) string {
	return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func writeLine(s string) {
	os.Stdout.WriteString(s + "\n")
}

// Paragraphs

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	curRec.BrBranch = line[0:2]
	curRec.BrAcct = line[2:6]
	curRec.BrType = line[6:7]
	amtStr := line[7:14]
	curRec.BrAmt = parseAmt(amtStr)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		newBal := WsBal.Add(curRec.BrAmt)
		WsBal = storeWithDigits(newBal, 7, 2)
		line := curRec.BrAcct + " D " + WsAmtEd
		writeLine(line)
	case "C":
		newBal := WsBal.Sub(curRec.BrAmt)
		WsBal = storeWithDigits(newBal, 7, 2)
		line := curRec.BrAcct + " C " + WsAmtEd
		writeLine(line)
	default:
		newSkipped := WsSkipped + 1
		WsSkipped = storeSkipped(newSkipped)
		line := curRec.BrAcct + " ? SKIPPED"
		writeLine(line)
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	line := "  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd
	writeLine(line)
	newBranchTot := WsBranchTot.Add(WsBal)
	WsBranchTot = storeWithDigits(newBranchTot, 9, 2)
	WsBal = decimal.Zero
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	line := " BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd
	writeLine(line)
	newGrand := WsGrandTot.Add(WsBranchTot)
	WsGrandTot = storeWithDigits(newGrand, 9, 2)
	WsBranchTot = decimal.Zero
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	line := "GRAND TOTAL:" + WsTotEd
	writeLine(line)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	line2 := "SKIPPED: " + skippedStr
	writeLine(line2)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	inputLines = nil
	inputIdx = 0
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		inputLines = append(inputLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		os.Exit(1)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
